namespace gpuastc {

// ---------------------------------------------------------------------------
// Two-partition patterns of a 4x4 block. The format derives each pattern from a 10 bit seed with
// a hash (ASTC specification, "Partition Pattern Generation"); the shader needs the reverse: for
// a wanted split of the 16 texels, the seed whose pattern is closest.
// ---------------------------------------------------------------------------

static uint32_t hash52(uint32_t p)
{
    p ^= p >> 15; p -= p << 17; p += p << 7; p += p << 4;
    p ^= p >> 5;  p += p << 16; p ^= p >> 7; p ^= p >> 3;
    p ^= p << 6;  p ^= p >> 17;
    return p;
}

// Group (0 or 1) of texel (x, y) for a two-partition seed. small: the block has under 31 texels.
static int select_partition2(int seed, int x, int y, bool small = true)
{
    if (small) { x <<= 1; y <<= 1; }
    seed += 1024;     // (partition count - 1) * 1024
    const uint32_t r = hash52((uint32_t)seed);
    int s1 = r & 0xF, s2 = (r >> 4) & 0xF, s3 = (r >> 8) & 0xF, s4 = (r >> 12) & 0xF;
    s1 *= s1; s2 *= s2; s3 *= s3; s4 *= s4;
    const int sh1 = (seed & 1) ? ((seed & 2) ? 4 : 5) : 5;
    const int sh2 = (seed & 1) ? 5 : ((seed & 2) ? 4 : 5);
    s1 >>= sh1; s2 >>= sh2; s3 >>= sh1; s4 >>= sh2;
    const int a = (s1 * x + s2 * y + (int)(r >> 14)) & 0x3F;
    const int b = (s3 * x + s4 * y + (int)(r >> 10)) & 0x3F;
    return a >= b ? 0 : 1;
}

// 65536 entries: seed | texels that differ << 10 | the pattern's own mask << 16.
// Bit i of a mask is the group of texel i (x + 4 * y).
static std::vector<uint32_t> build_partition_table()
{
    std::vector<uint32_t> val(65536, 0);
    std::vector<uint8_t> dist(65536, 99);
    for (int seed = 1023; seed >= 0; --seed) { // lowest seed wins
        uint32_t mask = 0;
        for (int i = 0; i < 16; ++i)
            mask |= (uint32_t)select_partition2(seed, i & 3, i >> 2) << i;
        if (mask == 0 || mask == 0xFFFF)
            continue; // everything in one group
        for (uint32_t m : {mask, mask ^ 0xFFFFu}) {
            dist[m] = 0;
            val[m] = (uint32_t)seed | (mask << 16);
        }
    }
    // Every other mask takes the pattern of a neighbour (one texel flipped) that is closer to
    // one, texel by texel, until nothing changes. Which of several equally close patterns a
    // mask ends up with depends on this order; of the orders tried this one scored best by a
    // small margin, and tests/partition_lut.py builds the table the same way.
    for (bool changed = true; changed;) {
        changed = false;
        for (int b = 0; b < 16; ++b)
            for (uint32_t m = 0; m < 65536; ++m) {
                const uint32_t n = m ^ (1u << b);
                if (dist[n] + 1 < dist[m]) {
                    dist[m] = (uint8_t)(dist[n] + 1);
                    val[m] = val[n];
                    changed = true;
                }
            }
    }
    for (int m = 0; m < 65536; ++m)
        val[m] |= (uint32_t)dist[m] << 10;
    return val;
}

// 5x5 and 6x6: a mask no longer fits a table index. The table is keyed by a 16-texel sample of
// the wanted split (rows and columns 0,1,3,4 or 0,2,3,5) and names the three patterns closest on
// that sample; the shader compares those three in full. Masks hold rows 0-2 in the first word
// and the remaining rows in the second, dim bits per row.
// 264 rows of 256: rows 0-255 seed0 | seed1 << 10 | seed2 << 20 by key, rows 256-263 the two mask
// words of every seed.
static std::vector<uint32_t> build_big_partition_table(int dim)
{
    const bool small = dim * dim < 31;
    const int sample[2][4] = {{0, 1, 3, 4}, {0, 2, 3, 5}};
    const int* at = sample[dim == 5 ? 0 : 1];
    const uint32_t all_lo = (1u << (3 * dim)) - 1, all_hi = (1u << ((dim - 3) * dim)) - 1;

    std::vector<uint32_t> table(256 * 264, 0);
    std::vector<uint64_t> seen;   // distinct splits so far (the smaller of a mask and its complement)
    std::vector<uint16_t> seeds, sig;
    for (int seed = 0; seed < 1024; ++seed) {
        uint32_t lo = 0, hi = 0;
        for (int y = 0; y < dim; ++y)
            for (int x = 0; x < dim; ++x)
                if (select_partition2(seed, x, y, small)) {
                    if (y < 3) lo |= 1u << (dim * y + x);
                    else       hi |= 1u << (dim * (y - 3) + x);
                }
        table[65536 + 2 * seed] = lo;
        table[65536 + 2 * seed + 1] = hi;
        if ((lo == 0 && hi == 0) || (lo == all_lo && hi == all_hi))
            continue; // everything in one group
        const uint64_t a = ((uint64_t)lo << 32) | hi, b = ((uint64_t)(lo ^ all_lo) << 32) | (hi ^ all_hi);
        const uint64_t canon = a < b ? a : b;
        bool dup = false;
        for (uint64_t c : seen) if (c == canon) { dup = true; break; }
        if (dup) continue; // the lowest seed of each distinct split
        seen.push_back(canon);
        uint32_t key = 0;
        for (int r = 0; r < 4; ++r) {
            const uint32_t row = at[r] < 3 ? lo >> (dim * at[r]) : hi >> (dim * (at[r] - 3));
            for (int c = 0; c < 4; ++c)
                key |= ((row >> at[c]) & 1u) << (4 * r + c);
        }
        seeds.push_back((uint16_t)seed);
        sig.push_back((uint16_t)key);
    }

    // For every key the three smallest of distance * 2048 + position (nearest first, lowest
    // seed on ties). A key and its complement have the same answer, so half the keys are scanned.
    uint8_t bits[256]; // set bits of a byte: a table this small stays in the first-level cache
    bits[0] = 0;
    for (uint32_t i = 1; i < 256; ++i) bits[i] = (uint8_t)(bits[i >> 1] + (i & 1));
    const uint16_t* const sg = sig.data();
    const size_t n = seeds.size();
    for (uint32_t key = 0; key < 32768; ++key) {
        uint32_t best[3] = {~0u, ~0u, ~0u};
        for (size_t i = 0; i < n; ++i) {
            const uint32_t x = key ^ sg[i];
            uint32_t d = (uint32_t)bits[x & 255] + bits[x >> 8];
            if (d > 8) d = 16 - d;
            const uint32_t v = d * 2048 + (uint32_t)i;
            if (v >= best[2]) continue;
            if (v < best[0])      { best[2] = best[1]; best[1] = best[0]; best[0] = v; }
            else if (v < best[1]) { best[2] = best[1]; best[1] = v; }
            else                  { best[2] = v; }
        }
        table[key] = table[key ^ 0xFFFFu] = (uint32_t)seeds[best[0] & 2047] | ((uint32_t)seeds[best[1] & 2047] << 10)
                                          | ((uint32_t)seeds[best[2] & 2047] << 20);
    }
    return table;
}

// Building the 5x5 or 6x6 table takes 0.2 to 0.4 s on a handheld's CPU, so it is kept next to
// the cached shaders. File: "GASTCTAB" (8 bytes), FNV-1a of the entries (8), the entries.
static uint64_t table_hash(const std::vector<uint32_t>& t)
{
    uint64_t h = 1469598103934665603ull;
    for (uint32_t v : t) { h ^= v; h *= 1099511628211ull; }
    return h;
}

static std::vector<uint32_t> big_partition_table(int dim, const std::string& cache_dir)
{
    const size_t count = 256 * 264;
    const std::string path = cache_dir.empty() ? std::string()
                           : cache_dir + "/gpuastc-patterns-" + std::to_string(dim) + "x" + std::to_string(dim) + "-1.bin";
    std::vector<uint32_t> table(count);
    if (!path.empty()) {
        if (FILE* f = std::fopen(path.c_str(), "rb")) {
            uint8_t hdr[16];
            uint64_t h = 0;
            bool ok = std::fread(hdr, 1, sizeof(hdr), f) == sizeof(hdr) && std::memcmp(hdr, "GASTCTAB", 8) == 0
                   && std::fread(table.data(), 4, count, f) == count;
            std::fclose(f);
            if (ok) {
                std::memcpy(&h, hdr + 8, 8);
                if (h == table_hash(table)) return table;
            }
        }
    }
    table = build_big_partition_table(dim);
    if (!path.empty()) {
        const std::string tmp = path + ".tmp";
        if (FILE* f = std::fopen(tmp.c_str(), "wb")) {
            const uint64_t h = table_hash(table);
            const bool ok = std::fwrite("GASTCTAB", 1, 8, f) == 8 && std::fwrite(&h, 8, 1, f) == 1
                         && std::fwrite(table.data(), 4, count, f) == count;
            if (std::fclose(f) != 0 || !ok || std::rename(tmp.c_str(), path.c_str()) != 0)
                std::remove(tmp.c_str());
        }
    }
    return table;
}

static GLuint g_partition_tex[3] = {0, 0, 0}; // 4x4, 5x5, 6x6: one per GL context, shared by every Encoder

static GLuint partition_texture(int block, const std::string& cache_dir)
{
    GLuint& tex = g_partition_tex[block - 4];
    if (!tex) {
        const std::vector<uint32_t> table = block == 4 ? build_partition_table() : big_partition_table(block, cache_dir);
        const GLsizei rows = (GLsizei)(table.size() / 256);
        glGenTextures(1, &tex);
        glBindTexture(GL_TEXTURE_2D, tex);
        glTexStorage2D(GL_TEXTURE_2D, 1, GL_R32UI, 256, rows);
        glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, 256, rows, GL_RED_INTEGER, GL_UNSIGNED_INT, table.data());
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    }
    return tex;
}

// ---------------------------------------------------------------------------
// Compiled-program cache. Compiling one variant takes a few tenths of a second on a handheld
// GPU; the driver can hand back the linked program as a blob (glGetProgramBinary) and take it
// again on a later run. The file name is a hash of the complete shader source and the driver's
// renderer and version strings, so a changed shader or driver simply misses.
// File: "GASTCBIN" (8 bytes), binary format (4), length (4), blob.
// ---------------------------------------------------------------------------

static uint64_t fnv1a64(const char* p, size_t n, uint64_t h)
{
    for (size_t i = 0; i < n; ++i) { h ^= (uint8_t)p[i]; h *= 1099511628211ull; }
    return h;
}

static std::string cache_path(const std::string& dir, const std::string& src)
{
    uint64_t h = fnv1a64(src.data(), src.size(), 1469598103934665603ull);
    for (GLenum name : {GL_RENDERER, GL_VERSION}) {
        const char* s = (const char*)glGetString(name);
        if (s) h = fnv1a64(s, std::strlen(s), h);
    }
    char name[48];
    std::snprintf(name, sizeof(name), "/gpuastc-%016llx.bin", (unsigned long long)h);
    return dir + name;
}

static GLuint load_cached_program(const std::string& path)
{
    FILE* f = std::fopen(path.c_str(), "rb");
    if (!f) return 0;
    uint8_t hdr[16];
    std::vector<uint8_t> blob;
    bool ok = std::fread(hdr, 1, sizeof(hdr), f) == sizeof(hdr) && std::memcmp(hdr, "GASTCBIN", 8) == 0;
    uint32_t format = 0, len = 0;
    if (ok) {
        std::memcpy(&format, hdr + 8, 4);
        std::memcpy(&len, hdr + 12, 4);
        ok = len > 0 && len < (64u << 20);
    }
    if (ok) {
        blob.resize(len);
        ok = std::fread(blob.data(), 1, len, f) == len;
    }
    std::fclose(f);
    if (!ok) return 0;

    while (glGetError() != GL_NO_ERROR) {}
    const GLuint prog = glCreateProgram();
    glProgramBinary(prog, (GLenum)format, blob.data(), (GLsizei)len);
    GLint linked = 0;
    glGetProgramiv(prog, GL_LINK_STATUS, &linked);
    if (glGetError() != GL_NO_ERROR || !linked) { // the driver no longer accepts it: compile again
        glDeleteProgram(prog);
        return 0;
    }
    return prog;
}

static void save_cached_program(const std::string& path, GLuint prog)
{
    GLint formats = 0, len = 0;
    glGetIntegerv(GL_NUM_PROGRAM_BINARY_FORMATS, &formats);
    glGetProgramiv(prog, GL_PROGRAM_BINARY_LENGTH, &len);
    if (formats <= 0 || len <= 0) return; // this driver does not hand out binaries
    std::vector<uint8_t> blob((size_t)len);
    GLenum format = 0;
    GLsizei written = 0;
    while (glGetError() != GL_NO_ERROR) {}
    glGetProgramBinary(prog, len, &written, &format, blob.data());
    if (glGetError() != GL_NO_ERROR || written <= 0) return;

    const std::string tmp = path + ".tmp";
    FILE* f = std::fopen(tmp.c_str(), "wb");
    if (!f) return;
    uint8_t hdr[16];
    const uint32_t fmt32 = (uint32_t)format, len32 = (uint32_t)written;
    std::memcpy(hdr, "GASTCBIN", 8);
    std::memcpy(hdr + 8, &fmt32, 4);
    std::memcpy(hdr + 12, &len32, 4);
    const bool ok = std::fwrite(hdr, 1, sizeof(hdr), f) == sizeof(hdr) && std::fwrite(blob.data(), 1, len32, f) == len32;
    if (std::fclose(f) != 0 || !ok || std::rename(tmp.c_str(), path.c_str()) != 0)
        std::remove(tmp.c_str());
}

GLenum Encoder::internal_format(int block)
{
    switch (block) {
    case 6:  return 0x93B4u; // GL_COMPRESSED_RGBA_ASTC_6x6_KHR
    case 5:  return 0x93B2u; // GL_COMPRESSED_RGBA_ASTC_5x5_KHR
    default: return 0x93B0u; // GL_COMPRESSED_RGBA_ASTC_4x4_KHR
    }
}

int Encoder::pick_block(int width, int height, bool alpha)
{
    const long long area = (long long)width * height;
    const int shortest = width < height ? width : height;
    if (alpha || shortest <= 64 || area <= 256LL * 256)
        return 4;
    if (area <= 2048LL * 2048)
        return 5;
    return 6;
}

Encoder::~Encoder() { destroy(); }

void Encoder::destroy()
{
    if (program_) {
        glDeleteProgram(program_);
        program_ = 0;
    }
    if (in_buffer_) {
        glDeleteBuffers(1, &in_buffer_);
        in_buffer_ = 0;
    }
}

bool Encoder::create(const Options& opt, std::string* log)
{
    destroy();
    opt_ = opt;

    std::string src = "#version 310 es\n";
    src += "#define BLOCK_DIM " + std::to_string(opt.block) + "\n";
    src += std::string("#define HAS_ALPHA ") + (opt.alpha ? "1" : "0") + "\n";
    src += std::string("#define PREMULTIPLIED ") + (opt.alpha && opt.premultiplied ? "1" : "0") + "\n";
    src += std::string("#define IS_NORMALMAP ") + (opt.normal_map ? "1" : "0") + "\n";
    src += std::string("#define INPUT_BUFFER ") + (opt.input_buffer ? "1" : "0") + "\n";
    if (opt.quality <= 0)
        src += "#define USE_PARTITIONS 0\n";
    else if (opt.quality >= 2)
        src += "#define PART_CANDIDATES 3\n#define ALT_ERR_THRESHOLD 64.0\n"
               "#define BIG_CANDIDATES 3\n#define BIG_ERR_THRESHOLD 32.0\n#define BIG_MAX_MISMATCH 5\n";
    // Tuning hook: GPUASTC_SHADER_DEFINES="NAME=VALUE;NAME=VALUE" overrides shader defaults
    // (ALT_ERR_THRESHOLD, PART_CANDIDATES, USE_PARTITIONS, ...).
    if (const char* extra = std::getenv("GPUASTC_SHADER_DEFINES")) {
        std::string def;
        for (const char* c = extra;; ++c) {
            if (*c == ';' || *c == 0) {
                if (!def.empty()) src += "#define " + def + "\n";
                def.clear();
                if (*c == 0) break;
            } else {
                def += (*c == '=') ? ' ' : *c;
            }
        }
    }
    // Development hook: GPUASTC_SHADER=<file> replaces the built-in shader source.
    std::string body = kShaderSource;
    if (const char* path = std::getenv("GPUASTC_SHADER")) {
        if (FILE* f = std::fopen(path, "rb")) {
            body.clear();
            char chunk[4096];
            for (size_t got; (got = std::fread(chunk, 1, sizeof chunk, f)) > 0;)
                body.append(chunk, got);
            std::fclose(f);
        }
    }
    src += body;

    from_cache_ = false;
    const std::string cached = opt.cache_dir.empty() ? std::string() : cache_path(opt.cache_dir, src);
    if (!cached.empty())
        program_ = load_cached_program(cached);
    if (program_) {
        from_cache_ = true;
    } else {
    GLuint sh = glCreateShader(GL_COMPUTE_SHADER);
    const char* p = src.c_str();
    glShaderSource(sh, 1, &p, nullptr);
    glCompileShader(sh);

    auto get_log = [&](bool is_prog, GLuint obj) {
        GLint len = 0;
        if (is_prog) glGetProgramiv(obj, GL_INFO_LOG_LENGTH, &len);
        else glGetShaderiv(obj, GL_INFO_LOG_LENGTH, &len);
        std::string s(len > 1 ? len : 1, '\0');
        if (is_prog) glGetProgramInfoLog(obj, len, nullptr, &s[0]);
        else glGetShaderInfoLog(obj, len, nullptr, &s[0]);
        return s;
    };

    GLint ok = 0;
    glGetShaderiv(sh, GL_COMPILE_STATUS, &ok);
    if (!ok) {
        if (log) *log = get_log(false, sh);
        glDeleteShader(sh);
        return false;
    }

    program_ = glCreateProgram();
    glAttachShader(program_, sh);
    glLinkProgram(program_);
    glDeleteShader(sh);

    glGetProgramiv(program_, GL_LINK_STATUS, &ok);
    if (!ok) {
        if (log) *log = get_log(true, program_);
        destroy();
        return false;
    }
    if (!cached.empty())
        save_cached_program(cached, program_);
    }

    if (opt.quality > 0 && (opt.block == 4 || !opt.alpha))
        partition_texture(opt.block, opt.cache_dir); // built here so the first encode does not pay for it
    loc_tex_size_ = glGetUniformLocation(program_, "uTexSize");
    loc_blocks_ = glGetUniformLocation(program_, "uBlocks");
    loc_count_ = glGetUniformLocation(program_, "uN");
    loc_row0_ = glGetUniformLocation(program_, "uRow0");
    return true;
}

bool Encoder::buffer_input_fits(int width, int height)
{
    GLint64 max_block = 0;
    glGetInteger64v(GL_MAX_SHADER_STORAGE_BLOCK_SIZE, &max_block);
    return (GLint64)width * height * 4 <= max_block;
}

bool Encoder::encode(GLuint tex, int width, int height, GLuint out_buffer)
{
    if (!program_ || opt_.input_buffer || width <= 0 || height <= 0)
        return false;
    glActiveTexture(GL_TEXTURE0);
    glBindTexture(GL_TEXTURE_2D, tex);
    return dispatch(width, height, out_buffer);
}

bool Encoder::encode_pixels(const uint8_t* rgba, int width, int height, GLuint out_buffer)
{
    if (!program_ || !opt_.input_buffer || width <= 0 || height <= 0)
        return false;
    if (!in_buffer_) glGenBuffers(1, &in_buffer_);
    glBindBuffer(GL_SHADER_STORAGE_BUFFER, in_buffer_);
    glBufferData(GL_SHADER_STORAGE_BUFFER, (GLsizeiptr)width * height * 4, rgba, GL_STREAM_DRAW);
    glBindBufferBase(GL_SHADER_STORAGE_BUFFER, 1, in_buffer_);
    return dispatch(width, height, out_buffer);
}

bool Encoder::dispatch(int width, int height, GLuint out_buffer)
{
    const int bx = blocks(width, opt_.block);
    const int by = blocks(height, opt_.block);

    glBindBuffer(GL_SHADER_STORAGE_BUFFER, out_buffer);
    glBufferData(GL_SHADER_STORAGE_BUFFER, (GLsizeiptr)bx * by * 16, nullptr, GL_DYNAMIC_COPY);
    glBindBufferBase(GL_SHADER_STORAGE_BUFFER, 0, out_buffer);

    if (opt_.quality > 0 && (opt_.block == 4 || !opt_.alpha)) { // partition patterns, texture unit 1
        const GLuint table = partition_texture(opt_.block, opt_.cache_dir);
        glActiveTexture(GL_TEXTURE1);
        glBindTexture(GL_TEXTURE_2D, table);
        glActiveTexture(GL_TEXTURE0);
    }

    glUseProgram(program_);
    glUniform2i(loc_tex_size_, width, height);
    glUniform2i(loc_blocks_, bx, by);
    glUniform1i(loc_count_, opt_.block * opt_.block); // texels per block; keeps shader loops rolled
    // In bands of about 16000 blocks, each its own GPU job: Panfrost's kernel driver gives a job
    // half a second and then stops it, which left the lower part of big images unencoded.
    const int band = std::max(8, (16384 / bx) & ~7);
    for (int row = 0; row < by; row += band) {
        glUniform1i(loc_row0_, row);
        glDispatchCompute((bx + 7) / 8, (std::min(band, by - row) + 7) / 8, 1);
        glFlush();
    }

    glMemoryBarrier(GL_BUFFER_UPDATE_BARRIER_BIT | GL_PIXEL_BUFFER_BARRIER_BIT);
    return glGetError() == GL_NO_ERROR;
}

} // namespace gpuastc
